import{_ as s,o as i,c as a,ag as d}from"./chunks/framework.DHSXpJLs.js";const k=JSON.parse('{"title":"CAD 编辑服务（services/cad）","description":"","frontmatter":{},"headers":[],"relativePath":"development/cad-service.md","filePath":"development/cad-service.md","lastUpdated":1790781261000}'),t={name:"development/cad-service.md"};function o(r,e,c,n,l,h){return i(),a("div",null,[...e[0]||(e[0]=[d(`<h1 id="cad-编辑服务-services-cad" tabindex="-1">CAD 编辑服务（services/cad） <a class="header-anchor" href="#cad-编辑服务-services-cad" aria-label="Permalink to &quot;CAD 编辑服务（services/cad）&quot;">​</a></h1><p><code>services/cad/</code> 是 Python FastAPI 服务，基于 ezdxf，默认端口 8200，与 <code>services/ifc</code> 同构：脚本沙箱、10 步暂存、大版本快照、定位、标量改写、diff 一应俱全，另外负责发布 render.json 给前端画布。</p><h2 id="与-ifc-侧的差异" tabindex="-1">与 IFC 侧的差异 <a class="header-anchor" href="#与-ifc-侧的差异" aria-label="Permalink to &quot;与 IFC 侧的差异&quot;">​</a></h2><ul><li>模型文件是 <code>uploads/{id}.dxf</code>，产物是 <code>out.dxf</code>。</li><li><strong>没有内存实体缓存</strong>，也没有直改时代的遗留概念（无 <code>pending</code>、<code>history</code>）。</li><li>版本与对比齐备，但对齐口径不同：定位按实体 key 查而非 guid，key 存在 DXF 的 XDATA 扩展数据里；diff 是实体级的，IFC 侧是属性级。</li><li>run/save 成功后<strong>原子发布 render.json</strong>，这是 IFC 侧没有的一步。</li></ul><h2 id="运行与配置" tabindex="-1">运行与配置 <a class="header-anchor" href="#运行与配置" aria-label="Permalink to &quot;运行与配置&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> services/cad</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sync</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">VIEWER_DATA_DIR</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">realpath</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ../../data)&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> uvicorn</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> app.main:app</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --port</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8200</span></span></code></pre></div><p>环境变量（<code>VIEWER_DATA_DIR</code>、<code>CAD_SERVICE_PORT</code>、<code>AIDXF_FLOWS_DIR</code>、<code>AIDXF_DRAWLIB_DIR</code>、<code>CAD_SERVICE_MAX_MODELS</code> 等）与沙箱变量集中在<a href="/SourceAEC/guide/configuration">配置说明</a>，沙箱机制见<a href="/SourceAEC/development/sandbox">沙箱执行环境</a>。</p><h2 id="端点" tabindex="-1">端点 <a class="header-anchor" href="#端点" aria-label="Permalink to &quot;端点&quot;">​</a></h2><p>脚本编辑面与 IFC 侧是同一套，语义见 <a href="/SourceAEC/reference/edit-api">IFC 编辑 API</a>：</p><table tabindex="0"><thead><tr><th>分组</th><th>端点</th></tr></thead><tbody><tr><td>读取与暂存</td><td><code>GET/PUT /models/{id}/script</code>、<code>script/params</code>、<code>script/undo|redo|discard</code></td></tr><tr><td>沙箱与版本</td><td><code>POST /models/{id}/script/run</code>、<code>save</code>、<code>rollback</code>。成功后原子发布 render.json</td></tr><tr><td>版本与对比</td><td><code>GET /models/{id}/scripts</code>、<code>script/diff</code>、<code>script/staging/diff</code>、<code>GET /models/{id}/versions</code>、<code>POST /models/{id}/diff</code></td></tr><tr><td>定位与改写</td><td><code>GET /models/{id}/script/locate?key=</code>、<code>POST /models/{id}/script/edit-call</code>（仅直连）</td></tr><tr><td>渲染载荷</td><td><code>GET /models/{id}/render.json</code>。已发布时直接读文件，未发布时即时生成</td></tr></tbody></table><p>Go server 按模型 kind 分流：dxf 模型的请求代理到 8200，对外路径不变。render.json 另外经 <code>GET /v1/models/{id}/render.json</code> 只读直挂，schema 见<a href="/SourceAEC/reference/api-model#render-json-schema">模型与审查 API</a>。</p><p>render.json 的发布不阻断主流程：生成或写盘失败只记 warning，并<strong>主动删除旧的 render.json</strong>，防止旧 payload 与新的 uploads 文件错位。所以前端拿不到渲染数据时，看服务日志有没有这条 warning。</p><h2 id="实现要点" tabindex="-1">实现要点 <a class="header-anchor" href="#实现要点" aria-label="Permalink to &quot;实现要点&quot;">​</a></h2><ul><li>七个领域模块来自共享包 <code>aibim_sandbox</code>，REST 编辑面来自 <code>aibim_editapi</code>，与 services/ifc 同一事实源，本服务只留薄适配。</li><li><code>app/dxf_diffing.py</code> 做实体级 diff；<code>app/dxf_materialize.py</code> 按需重建历史版本；<code>app/render.py</code> 把 DXF 转成 render.json，坐标保持原始 DXF 坐标系。</li><li>契约层在 <code>services/cad/flows/</code>，提供脚本校验和确定性 key。</li></ul><h2 id="测试" tabindex="-1">测试 <a class="header-anchor" href="#测试" aria-label="Permalink to &quot;测试&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> services/cad</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --group</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pytest</span></span></code></pre></div>`,16)])])}const F=s(t,[["render",o]]);export{k as __pageData,F as default};
